// CheckoutScreen.tsx
import React, { useEffect, useMemo, useState, useCallback } from 'react';
import { CartItem, DeliveryAddress, AddressErrors } from './types';
import { getTelegram } from './telegram';
import './CheckoutScreen.css';

interface CheckoutScreenProps {
  items: CartItem[];
  currency?: string;
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress, total: number) => Promise<void> | void;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

const DELIVERY_FEE = 4.99;

function formatPrice(value: number, currency: string): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: 2,
  }).format(value);
}

function validate(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Full name is required';
  }
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required';
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }
  if (!address.city.trim()) {
    errors.city = 'City is required';
  }
  if (!address.street.trim()) {
    errors.street = 'Street address is required';
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required';
  }

  return errors;
}

export default function CheckoutScreen({
  items,
  currency = 'USD',
  onBackToCart,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isPaying, setIsPaying] = useState(false);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = useMemo(
    () => (items.length ? subtotal + DELIVERY_FEE : 0),
    [subtotal, items.length]
  );

  const isFormValid = useMemo(() => {
    const currentErrors = validate(address);
    return Object.keys(currentErrors).length === 0 && items.length > 0;
  }, [address, items.length]);

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const value = e.target.value;
    setAddress((prev) => ({ ...prev, [field]: value }));
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validate({ ...address }));
  };

  const handlePay = useCallback(async () => {
    const tg = getTelegram();
    const currentErrors = validate(address);
    setErrors(currentErrors);
    setTouched({
      fullName: true,
      phone: true,
      city: true,
      street: true,
      apartment: true,
      postalCode: true,
      comment: true,
    });

    if (Object.keys(currentErrors).length > 0) {
      tg?.HapticFeedback.notificationOccurred('error');
      tg?.showAlert('Please fill in all required delivery fields.');
      return;
    }
    if (items.length === 0) return;

    try {
      setIsPaying(true);
      tg?.MainButton.showProgress(true);
      await onPay(address, total);
      tg?.HapticFeedback.notificationOccurred('success');
    } finally {
      setIsPaying(false);
      tg?.MainButton.hideProgress();
    }
  }, [address, items.length, onPay, total]);

  // Wire up Telegram's native BackButton + MainButton instead of (or alongside) in-page controls.
  useEffect(() => {
    const tg = getTelegram();
    if (!tg) return;

    tg.BackButton.show();
    tg.BackButton.onClick(onBackToCart);

    tg.MainButton.setText(
      items.length ? `Pay ${formatPrice(total, currency)}` : 'Your cart is empty'
    );
    tg.MainButton.show();
    if (isFormValid && !isPaying) {
      tg.MainButton.enable();
    } else {
      tg.MainButton.disable();
    }
    tg.MainButton.onClick(handlePay);

    return () => {
      tg.BackButton.hide();
      tg.BackButton.offClick(onBackToCart);
      tg.MainButton.offClick(handlePay);
      tg.MainButton.hide();
    };
  }, [currency, handlePay, isFormValid, isPaying, items.length, onBackToCart, total]);

  const fieldError = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  return (
    <div className="checkout">
      <header className="checkout__header">
        <button
          type="button"
          className="checkout__back-btn"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          <span className="checkout__back-icon" aria-hidden="true">‹</span>
          Back to cart
        </button>
        <h1 className="checkout__title">Checkout</h1>
      </header>

      <section className="checkout__section" aria-labelledby="order-summary-heading">
        <h2 id="order-summary-heading" className="checkout__section-title">
          Order summary
        </h2>

        {items.length === 0 ? (
          <p className="checkout__empty">Your cart is empty.</p>
        ) : (
          <ul className="checkout__items">
            {items.map((item) => (
              <li key={item.id} className="checkout-item">
                <img
                  src={item.imageUrl}
                  alt=""
                  className="checkout-item__image"
                />
                <div className="checkout-item__info">
                  <span className="checkout-item__name">{item.name}</span>
                  <span className="checkout-item__qty">Qty {item.quantity}</span>
                </div>
                <span className="checkout-item__price">
                  {formatPrice(item.price * item.quantity, currency)}
                </span>
              </li>
            ))}
          </ul>
        )}

        <div className="checkout__totals">
          <div className="checkout__totals-row">
            <span>Subtotal</span>
            <span>{formatPrice(subtotal, currency)}</span>
          </div>
          <div className="checkout__totals-row">
            <span>Delivery</span>
            <span>{items.length ? formatPrice(DELIVERY_FEE, currency) : '—'}</span>
          </div>
          <div className="checkout__totals-row checkout__totals-row--total">
            <span>Total</span>
            <span>{formatPrice(total, currency)}</span>
          </div>
        </div>
      </section>

      <section className="checkout__section" aria-labelledby="address-heading">
        <h2 id="address-heading" className="checkout__section-title">
          Delivery address
        </h2>

        <form
          className="checkout-form"
          noValidate
          onSubmit={(e) => {
            e.preventDefault();
            handlePay();
          }}
        >
          <div className="checkout-form__field">
            <label htmlFor="fullName">Full name</label>
            <input
              id="fullName"
              type="text"
              autoComplete="name"
              value={address.fullName}
              onChange={handleChange('fullName')}
              onBlur={handleBlur('fullName')}
              aria-invalid={!!fieldError('fullName')}
              aria-describedby="fullName-error"
            />
            {fieldError('fullName') && (
              <span id="fullName-error" className="checkout-form__error">
                {fieldError('fullName')}
              </span>
            )}
          </div>

          <div className="checkout-form__field">
            <label htmlFor="phone">Phone number</label>
            <input
              id="phone"
              type="tel"
              autoComplete="tel"
              placeholder="+1 555 123 4567"
              value={address.phone}
              onChange={handleChange('phone')}
              onBlur={handleBlur('phone')}
              aria-invalid={!!fieldError('phone')}
              aria-describedby="phone-error"
            />
            {fieldError('phone') && (
              <span id="phone-error" className="checkout-form__error">
                {fieldError('phone')}
              </span>
            )}
          </div>

          <div className="checkout-form__row">
            <div className="checkout-form__field">
              <label htmlFor="city">City</label>
              <input
                id="city"
                type="text"
                autoComplete="address-level2"
                value={address.city}
                onChange={handleChange('city')}
                onBlur={handleBlur('city')}
                aria-invalid={!!fieldError('city')}
              />
              {fieldError('city') && (
                <span className="checkout-form__error">{fieldError('city')}</span>
              )}
            </div>
            <div className="checkout-form__field">
              <label htmlFor="postalCode">Postal code</label>
              <input
                id="postalCode"
                type="text"
                autoComplete="postal-code"
                value={address.postalCode}
                onChange={handleChange('postalCode')}
                onBlur={handleBlur('postalCode')}
                aria-invalid={!!fieldError('postalCode')}
              />
              {fieldError('postalCode') && (
                <span className="checkout-form__error">{fieldError('postalCode')}</span>
              )}
            </div>
          </div>

          <div className="checkout-form__field">
            <label htmlFor="street">Street address</label>
            <input
              id="street"
              type="text"
              autoComplete="address-line1"
              value={address.street}
              onChange={handleChange('street')}
              onBlur={handleBlur('street')}
              aria-invalid={!!fieldError('street')}
            />
            {fieldError('street') && (
              <span className="checkout-form__error">{fieldError('street')}</span>
            )}
          </div>

          <div className="checkout-form__field">
            <label htmlFor="apartment">Apartment / suite (optional)</label>
            <input
              id="apartment"
              type="text"
              autoComplete="address-line2"
              value={address.apartment}
              onChange={handleChange('apartment')}
            />
          </div>

          <div className="checkout-form__field">
            <label htmlFor="comment">Delivery notes (optional)</label>
            <textarea
              id="comment"
              rows={3}
              value={address.comment}
              onChange={handleChange('comment')}
              placeholder="E.g. gate code, preferred time"
            />
          </div>

          {/* Fallback in-page Pay button, shown when the Telegram MainButton isn't available (e.g. during local dev in a plain browser). */}
          <button
            type="submit"
            className="checkout-form__pay-btn checkout-form__pay-btn--fallback"
            disabled={!isFormValid || isPaying}
          >
            {isPaying
              ? 'Processing…'
              : items.length
              ? `Pay ${formatPrice(total, currency)}`
              : 'Your cart is empty'}
          </button>
        </form>
      </section>
    </div>
  );
}
